contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newImpl, address newSettings) public {
        require(newImpl != address(0));
        require(newSettings != address(0));
        c.initialize();
        address ownerAfterInit = c.owner();
        bool createRevertedBefore;
        address beforeAddr;
        // create() must revert while alloSettings is still unset
        try c.create("", address(this)) { createRevertedBefore = false; beforeAddr = address(0); }
        catch { createRevertedBefore = true; }
        c.updateAlloSettings(newSettings);
        c.updateRoundImplementation(payable(newImpl));
        assert(
            ownerAfterInit == address(this) &&
            createRevertedBefore &&
            c.alloSettings() == newSettings &&
            c.roundImplementation() == newImpl &&
            c.owner() == address(this)
        );
    }
    receive() external payable {}
}

