contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address impl, address allo, address ownedBy, bytes calldata encodedParameters) public {
        c.initialize();
        // No public/external way exists to register a program operator,
        // so msg.sender (this contract) is never one.
        bool reverted;
        try c.create(encodedParameters, ownedBy) { reverted = false; }
        catch Error(string memory reason) {
            reverted = keccak256(bytes(reason)) == keccak256(bytes("Caller is not a program operator"));
        }
        catch { reverted = false; }
        assert(reverted);
    }
    receive() external payable {}
}

