contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address impl, address newSettings) public {
        c.initialize();
        bool revertedZero;
        try c.updateRoundImplementation(payable(address(0))) { revertedZero = false; } catch { revertedZero = true; }
        address before = c.roundImplementation();
        assert(revertedZero && before == address(0));
        c.updateAlloSettings(newSettings);
        assert(c.alloSettings() == newSettings);
        c.updateRoundImplementation(payable(impl));
        address stored = c.roundImplementation();
        assert(stored == (impl == address(0) ? before : impl));
        bool revertedNonOwner;
        // owner renounces: after renounce, onlyOwner calls must revert
        c.renounceOwnership();
        try c.updateAlloSettings(address(impl)) { revertedNonOwner = false; } catch { revertedNonOwner = true; }
        assert(revertedNonOwner && c.alloSettings() == newSettings);
    }
    receive() external payable {}
}

